export const TRANSMOG_FAIL_CHANCE = 0.2;
export const TRANSMOG_FAIL_ENERGY = 2;
export const TRANSMOG_FAIL_MOOD = 2;
export const TRANSMOG_FAIL_LINE = "Well, that didn't work. I suggest you get some more skillz!";

/** computeEnergyAndTimeCost: machines add 2200 ms once per batch for their animations. */
export const MACHINE_EXTRA_WAIT_MS = 2200;

/**
 * making_get_transmogrification_time: seconds for the nth unit of a batch
 * (2 s each for the first five, then 1, 0.5, 0.2 and 0.1 s).
 */
export function transmogUnitSeconds(n) {
  if (n <= 5) return 2;
  if (n <= 10) return 1;
  if (n <= 20) return 0.5;
  if (n <= 50) return 0.2;
  return 0.1;
}

/**
 * Tool-wear units a batch of `count` costs: ore_grinder.js
 * getToolWearMultiplier is round(count / 3) for rock (runSkillPackage turns
 * 0 into 1) and count for barnacles; every other tool wears per unit.
 */
export function batchWearUnits(recipe, count) {
  const n = Math.max(0, Math.floor(Number(count) || 0));
  if (!n) return 0;
  const grinder = recipe?.tool === 'ore_grinder' || recipe?.tool === 'grand_ol_grinder';
  const barnacle = (recipe?.inputs || []).some((inp) => inp.classTsid === 'barnacle');
  return grinder && !barnacle ? Math.round(n / 3) || 1 : n;
}

/** making_required_skill: the skill a tool needs, or null (transmogrifiers). */
export function makingRequiredSkill(toolId) {
  const rule = MAKING_TOOL_SKILLS[toolId];
  if (!rule || rule.makingType === 'transmogrification') return null;
  return rule.requiredSkill || null;
}

/**
 * Skill-adjusted per-unit energy and wait for a recipe, plus the unskilled
 * transmogrification failure chance. Without a learned list the catalog
 * values are returned unchanged.
 * @param {Recipe|null} recipe
 * @param {string[]} [learned]
 */
export function makingSkillAdjustments(recipe, learned, upgrades = []) {
  const baseEnergy = Number(recipe?.energyCost) || 0;
  const baseWait = Number(recipe?.waitMs) || 0;
  const rule = MAKING_TOOL_SKILLS[recipe?.tool] || null;
  const out = {
    energyCost: baseEnergy,
    waitMs: baseWait,
    waitMultiplier: 1,
    toolWear: null,
    failChance: 0,
    skillLevel: 0,
    requiredSkill: rule?.requiredSkill || null,
    makingType: rule?.makingType || '',
    note: '',
  };
  if (!rule || !Array.isArray(learned)) return out;
  if (rule.makingType === 'cooking') {
    const level = highestSkillLevel(learned, rule.requiredSkill);
    out.skillLevel = level;
    if (level >= 2) out.waitMultiplier = 0.5;
    if (level >= 3) out.energyCost = Math.round(baseEnergy * 0.67);
    else if (level >= 2) out.energyCost = Math.round(baseEnergy * 0.5);
    if (level >= 2) out.note = `Level ${level} cooking: half the time, less energy.`;
  } else if (rule.makingType === 'transmogrification') {
    if (!learned.includes(rule.requiredSkill)) {
      out.waitMultiplier = 2;
      out.energyCost = Math.round(baseEnergy * 1.25);
      out.failChance = TRANSMOG_FAIL_CHANCE;
      out.note = 'Unskilled: twice as slow, +25% energy, 20% chance to fail.';
    } else {
      out.skillLevel = 1;
    }
  } else if (recipe?.tool === 'ore_grinder' || recipe?.tool === 'grand_ol_grinder') {
    // The Grinder runs the `refining` package: Refining II takes half the
    // time (4 s to 2 s) and 3 energy per chunk instead of 4.
    // Refined Speed I/II (refining_time_1/2) shorten the package duration 20/40%.
    const barnacle = (recipe.inputs || []).some((inp) => inp.classTsid === 'barnacle');
    const refining = skillPackageDetails(barnacle ? 'barnacle_refining' : 'refining', barnacle ? ['no_skill'] : learned, upgrades);
    if (refining) {
      out.skillLevel = barnacle ? 0 : refining.rank;
      out.energyCost = refining.energy_cost;
      out.toolWear = refining.tool_wear;
      if (!barnacle) out.waitMultiplier = refining.duration / 4000;
      if (!barnacle && refining.rank >= 2) out.note = 'Refining II: twice as fast, 3 energy per chunk.';
    }
  } else if (recipe?.tool === 'blockmaker') {
    // inc_making.js:368-375: Better / Betterer Blockmaker burn 20 / 40% less
    // fuel (the recipe's fuel_cell input is the per-unit tank use here).
    const fuel = Number(recipe.toolWear) || 0;
    const saved = blockmakerFuel(fuel, upgrades);
    if (saved !== fuel) {
      out.toolWear = saved;
      out.note = `Uses ${saved} fuel instead of ${fuel}.`;
    }
  } else if (recipe?.tool === 'smelter') {
    // smelter.js runs the `smelting` package: 5 energy and 3 wear per ingot,
    // The Green Smelt 3 energy, Strong Smelter 2 wear.
    const smelting = skillPackageDetails('smelting', learned, upgrades);
    const cards = smeltingOverrides(upgrades);
    if (smelting) {
      // A running Smelt It, Dealt It sets the package's energy_cost override,
      // which getSkillPackageDetails writes last (over the cards' figure).
      out.energyCost = getSkillPackageOverride('smelting')?.energy_cost ?? cards.energyCost ?? smelting.energy_cost;
      out.toolWear = cards.toolWear ?? smelting.tool_wear;
    }
  }
  out.waitMs = Math.round(baseWait * out.waitMultiplier);
  return out;
}

/** Per-unit energy a recipe really costs this player. */
export function recipeEnergyCost(recipe, learned, upgrades = []) {
  return makingSkillAdjustments(recipe, learned, upgrades).energyCost;
}

/** Batch cap for recipes without a task_limit (the remake's old flat cap). */
export const DEFAULT_TASK_LIMIT = 99;

/**
 * The most units one make can ask for: the recipe's task_limit (main.js
 * recipe catalog, the client's quantity cap), after the batch-size cards
 * (get_task_limit_multiplier). Recipes the source gave no limit keep 99.
 */
export function recipeTaskLimit(recipe, upgrades = []) {
  const base = Number(recipe?.taskLimit) || 0;
  if (!(base > 0)) return DEFAULT_TASK_LIMIT;
  return Math.max(1, adjustedTaskLimit(base, recipe.tool, upgrades));
}

