/**
 * Ensure making items + tools exist on ITEM_CATALOG (mutates shared catalog).
 * Always refreshes icon paths to OGA iconic pack.
 */
export function ensureMakingItems() {
  for (const [id, meta] of Object.entries(MAKING_ITEM_EXTRAS)) {
    ensureItem(id, meta);
  }
  for (const [id, meta] of Object.entries(TOOL_CATALOG)) {
    ensureItem(id, {
      label: meta.label,
      desc: meta.desc,
      isTool: true,
    });
    // keep TOOL_CATALOG.icon in sync
    meta.icon = itemIcon(id);
  }
  // GSJS metadata: source label/description/base cost/stack cap/tags + eat/drink.
  for (const [id, meta] of Object.entries(MAKING_ITEM_META)) {
    const isTool = Boolean(TOOL_CATALOG[id]) || meta.isTool === true || ITEM_CATALOG[id]?.isTool === true;
    ensureItem(id, {
      label: TOOL_CATALOG[id]?.label || meta.label,
      desc: TOOL_CATALOG[id] ? undefined : meta.desc,
      baseCost: Number(meta.baseCost),
      stackMax: Number(meta.stackMax),
      tags: Array.isArray(meta.tags) ? meta.tags : undefined,
      namePlural: meta.namePlural,
      isTool,
    });
    if (meta.use && !isTool) registerItemUse(id, meta.use, { label: ITEM_CATALOG[id]?.label });
  }
  // Register any recipe I/O not yet catalogued
  for (const recipe of Object.values(RECIPE_CATALOG)) {
    for (const io of [...(recipe.inputs || []), ...(recipe.outputs || [])]) {
      ensureItem(io.classTsid);
    }
  }
}

export function listTools() {
  return Object.values(TOOL_CATALOG);
}

/** Tools that have at least one recipe (Make panel chips; excludes pick/fancy_pick). */
export function listMakingTools() {
  const used = new Set(Object.values(RECIPE_CATALOG).map((r) => r.tool));
  return Object.values(TOOL_CATALOG).filter((t) => used.has(t.classTsid));
}

/**
 * Search recipes by name, output/input label or class_tsid (case-insensitive).
 * @param {string} query
 * @param {{ tool?: string }} [opts]
 */
export function searchRecipes(query, opts = {}) {
  const q = String(query || '').trim().toLowerCase();
  const pool = (opts.tool && opts.tool !== 'all' ? listRecipesForTool(opts.tool) : listRecipes())
    .filter((r) => recipeKnown(r, opts.completedQuests));
  if (!q) return pool;
  return pool.filter((r) => {
    if (String(r.name || '').toLowerCase().includes(q)) return true;
    return [...(r.outputs || []), ...(r.inputs || [])].some((io) => {
      const label = ITEM_CATALOG[io.classTsid]?.label || '';
      return io.classTsid.toLowerCase().includes(q) || label.toLowerCase().includes(q);
    });
  });
}

/** Recipes that produce a class_tsid (pack popover "how do I make this?"). */
export function listRecipesProducing(classTsid) {
  return listRecipes().filter((r) => (r.outputs || []).some((o) => o.classTsid === classTsid));
}

/** A quest-taught recipe stays out of the catalog until its quest is done. */
export function recipeKnown(recipe, completedQuests = null) {
  return !recipe?.taughtBy || !Array.isArray(completedQuests) || completedQuests.includes(recipe.taughtBy);
}

export function listRecipes() {
  ensureMakingItems();
  return Object.entries(RECIPE_CATALOG).map(([key, recipe]) => ({
    key,
    ...recipe,
  }));
}

/**
 * @param {string} toolId
 */
export function listRecipesForTool(toolId) {
  const recipeTool = recipeToolFor(toolId);
  return listRecipes().filter((r) => r.tool === recipeTool);
}

/**
 * @param {import('./inventory.js').Inventory} inv
 * @param {string} toolId
 */
export function hasTool(inv, toolId) {
  if (!toolId) return true;
  return toolOptions(toolId).some((id) => countItem(inv, id) >= 1);
}

/**
 * Tools that make a recipe tool's recipes. Crush recipes name ore_grinder;
 * dullite.js:108,126 and barnacle.js:108,119 crush with a Grinder or a
 * Grand Ol' Grinder (craftytasking.js:737 'ore_grinder|grand_ol_grinder').
 */
export const TOOL_STAND_INS = Object.freeze({
  ore_grinder: GRINDER_TOOLS,
});

/** The recipe tool whose recipes a stand-in makes (grand_ol_grinder -> ore_grinder). */
export function recipeToolFor(toolId) {
  for (const [recipeTool, ids] of Object.entries(TOOL_STAND_INS)) {
    if (ids.includes(toolId)) return recipeTool;
  }
  return toolId;
}

function toolOptions(toolId) {
  return TOOL_STAND_INS[toolId] || [toolId];
}

/**
 * The tool class a recipe actually wears: the first owned stand-in that can
 * take `wear`, else the first owned one (so the broken-tool message names it).
 * @param {import('./inventory.js').Inventory} inv
 * @param {string} toolId  recipe.tool
 * @param {object|null} [toolState]
 * @param {number} [wear]
 */
export function recipeToolInUse(inv, toolId, toolState = null, wear = 1) {
  if (!toolId || !TOOL_STAND_INS[toolId]) return toolId;
  const pick = firstWorkingTool(toolState, inv, TOOL_STAND_INS[toolId], wear);
  return pick.tool || pick.fallback || toolId;
}

/**
 * @param {import('./inventory.js').Inventory} inv
 * @param {Recipe} recipe
 * @param {{ learned?: string[], requireSkill?: boolean, requireTool?: boolean }} [opts]
 */
/**
 * Holiday-only recipes: Pi (288) cooks only on Pi Day (inc_making.js
 * `recipe_id == 288 && isPiDay()`). js/features/seasons-feature.js installs
 * the season test; until it does every recipe is in season.
 */
export const SEASONAL_RECIPES = Object.freeze({ 288: 'pi_day' });
let seasonalRecipeCheck = () => true;

/** @param {(season: string) => boolean} fn */
export function setSeasonalRecipeCheck(fn) {
  seasonalRecipeCheck = typeof fn === 'function' ? fn : () => true;
}

export function canCraft(inv, recipe, opts = {}) {
  if (!recipe) return { ok: false, reason: 'unknown' };
  const season = SEASONAL_RECIPES[String(recipe.id ?? '')];
  if (season && seasonalRecipeCheck(season) === false) {
    return { ok: false, reason: 'season', season, msg: 'You can only make this item on Pi Day, observed on March 14.' };
  }

  const requireTool = opts.requireTool !== false;
  // A machine standing in the world (machine rooms, G169) is the tool: the
  // pack need not hold one, and opts.toolState is that machine's own tank.
  const atStation = Boolean(opts.stationTool) && recipe.tool === opts.stationTool;
  if (requireTool && recipe.tool && !atStation && !hasTool(inv, recipe.tool)) {
    const label = TOOL_CATALOG[recipe.tool]?.label || recipe.tool;
    return { ok: false, reason: 'tool', tool: recipe.tool, need: label };
  }
  if (requireTool && recipe.tool && opts.toolState) {
    const wear = opts.toolWear || recipe.toolWear || 1;
    const toolId = atStation ? recipe.tool : recipeToolInUse(inv, recipe.tool, opts.toolState, wear);
    const condition = canUseTool(opts.toolState, toolId, wear);
    if (!condition.ok) {
      return {
        ok: false,
        reason: 'broken_tool',
        tool: toolId,
        need: TOOL_CATALOG[toolId]?.label || toolId,
        msg: condition.msg,
      };
    }
  }

  // Enforce skills only when a learned list is provided (game path). The
  // source requires every listed skill (main.js recipe catalog `disabled`).
  const skillIds = [
    ...new Set([...(recipe.skill ? [recipe.skill] : []), ...(recipe.skills || [])]),
  ];
  if (skillIds.length && Array.isArray(opts.learned) && opts.requireSkill !== false) {
    const missingSkill = skillIds.find((id) => !opts.learned.includes(id));
    if (missingSkill) {
      return { ok: false, reason: 'skill', skill: missingSkill };
    }
  }
  // The tool itself needs its required_skill (except transmogrifiers):
  // making_can_use refuses a Frying Pan without Cheffery, and so on.
  // Verb recipes flagged toolSkillFree (Grinder barnacles) skip it.
  const toolSkill = recipe.toolSkillFree ? null : makingRequiredSkill(recipe.tool);
  if (toolSkill && Array.isArray(opts.learned) && opts.requireSkill !== false && !opts.learned.includes(toolSkill)) {
    return { ok: false, reason: 'skill', skill: toolSkill };
  }
  // Quest-taught recipes (learnt 3, making_try_learn_recipe from a quest's
  // onComplete) apply only when the caller passes the completed quest ids.
  if (recipe.taughtBy && Array.isArray(opts.completedQuests) && !opts.completedQuests.includes(recipe.taughtBy)) {
    return { ok: false, reason: 'quest', quest: recipe.taughtBy };
  }
  // Achievement-gated recipes (learnt 2) apply only when the caller passes
  // the unlocked achievement ids.
  if (
    recipe.achievements?.length &&
    Array.isArray(opts.achievements) &&
    opts.requireAchievement !== false
  ) {
    const missingAch = recipe.achievements.find((id) => !opts.achievements.includes(id));
    if (missingAch) {
      return { ok: false, reason: 'achievement', achievement: missingAch };
    }
  }

  for (const inp of recipe.inputs || []) {
    if (countItem(inv, inp.classTsid) < inp.qty) {
      return {
        ok: false,
        reason: 'ingredients',
        missing: inp.classTsid,
        need: inp.qty,
        have: countItem(inv, inp.classTsid),
      };
    }
  }
  return { ok: true, reason: 'ok' };
}

/**
 * Craft one recipe. Mutates inv and pc on success only.
 * @param {import('./inventory.js').Inventory} inv
 * @param {object} pc  { energy, mood, imagination, xp }
 * @param {string} recipeKey  key in RECIPE_CATALOG
 * @param {{ learned?: string[], requireSkill?: boolean, requireTool?: boolean }} [opts]
 */
export function craftRecipe(inv, pc, recipeKey, opts = {}) {
  ensureMakingItems();
  const recipe = RECIPE_CATALOG[recipeKey];
  if (!recipe) {
    return { ok: false, reason: 'unknown', msgs: ['Unknown recipe.'] };
  }

  const check = canCraft(inv, recipe, opts);
  if (!check.ok) {
    if (check.reason === 'tool') {
      return {
        ok: false,
        reason: 'tool',
        msgs: [`You need a ${check.need} to make that.`],
      };
    }
    if (check.reason === 'skill') {
      return {
        ok: false,
        reason: 'skill',
        msgs: [`You need the skill ${check.skill} first.`],
      };
    }
    if (check.reason === 'broken_tool') {
      return {
        ok: false,
        reason: 'broken_tool',
        msgs: [check.msg || `Your ${check.need} needs repairing.`],
      };
    }
    if (check.reason === 'quest') {
      return {
        ok: false,
        reason: 'quest',
        msgs: ["You haven't learned this recipe yet."],
      };
    }
    if (check.reason === 'achievement') {
      return {
        ok: false,
        reason: 'achievement',
        msgs: [`You need the ${check.achievement.replace(/_/g, ' ')} achievement first.`],
      };
    }
    if (check.reason === 'ingredients') {
      const label = ITEM_CATALOG[check.missing]?.label || check.missing;
      return {
        ok: false,
        reason: 'ingredients',
        msgs: [`Need ${check.need}× ${label} (have ${check.have}).`],
      };
    }
    return { ok: false, reason: check.reason, msgs: ['Cannot craft.'] };
  }

  const upgrades = Array.isArray(opts.upgrades) ? opts.upgrades : pc?.imaginationUpgrades || [];
  const adjust = makingSkillAdjustments(recipe, opts.learned, upgrades);
  const cost = adjust.energyCost;
  // getHitPointModifier: the *_tool_wear cards halve that cooking tool's wear.
  // The Grand Ol' Grinder makes the Grinder's recipes and takes their wear.
  const wornTool = opts.stationTool === recipe.tool
    ? recipe.tool
    : recipeToolInUse(inv, recipe.tool, opts.toolState, opts.toolWear || adjust.toolWear || recipe.toolWear || 1);
  const wearFor = (wear) => scaledToolWear(opts.toolState, wornTool, wear, toolWearMultiplier(wornTool, upgrades));
  // inc_making.js refuses when energy_cost >= energy.
  if ((pc.energy || 0) <= cost) {
    return {
      ok: false,
      reason: 'energy',
      msgs: [`Need ${cost} energy (you have ${Math.floor(pc.energy || 0)}).`],
    };
  }

  // A session commits a batch one unit at a time: unitIndex is this unit
  // (1-based) and batchQty the whole batch, for batch-level rules.
  const unitIndex = Math.max(1, Math.floor(Number(opts.unitIndex) || 1));
  const batchQty = Math.max(unitIndex, Math.floor(Number(opts.batchQty) || 1));
  const baseWear = opts.toolWear || adjust.toolWear || recipe.toolWear || 1;
  // Unskilled transmogrification: once per batch the tool takes the whole
  // batch's wear, then 20% of the time nothing is made and the player loses
  // a flat 2 energy and 2 mood (finishMakingKnown).
  if (adjust.failChance && unitIndex === 1 && !opts.maxLuck && (opts.rng || Math.random)() < adjust.failChance) {
    const failPoints = recipe.tool && opts.toolState ? wearFor(baseWear * batchWearUnits(recipe, batchQty)) : 0;
    const failWear = failPoints > 0 ? useToolCondition(opts.toolState, wornTool, failPoints) : null;
    // inc_making.js 792-794: metabolics_lose_energy(2) / _lose_mood(2), what they took in the line.
    const energyLost = loseEnergy(pc, TRANSMOG_FAIL_ENERGY);
    const moodLost = pc.mood != null ? loseMood(pc, TRANSMOG_FAIL_MOOD) : 0;
    return {
      ok: false,
      reason: 'transmog_failed',
      recipe,
      recipeKey,
      toolUse: failWear,
      energyLost,
      moodLost,
      msgs: [`${TRANSMOG_FAIL_LINE} (−${energyLost} energy, −${moodLost} mood)`],
    };
  }

  // Snapshot for atomicity
  const beforeInv = { ...inv };
  const beforeE = pc.energy;
  const beforeImg = pc.imagination;
  const beforeXp = pc.xp;

  for (const inp of recipe.inputs || []) {
    if (!removeItem(inv, inp.classTsid, inp.qty)) {
      Object.assign(inv, beforeInv);
      return { ok: false, reason: 'ingredients', msgs: ['Not enough ingredients.'] };
    }
  }

  // inc_making.js 1530: metabolics_lose_energy(energy_cost) (nothing while dead).
  const energyLost = loseEnergy(pc, cost);
  // inc_making.js 1546: stats_add_xp(actual, false) takes the mood bonus.
  const recipeXp = recipe.xpReward ? grantMoodXp(pc, recipe.xpReward) : 0;
  const rng = opts.rng || Math.random;
  if (unitIndex === 1 || batchExtras?.recipeKey !== recipeKey) {
    batchExtras = { recipeKey, swap: null, items: [], lines: [], xp: 0 };
    // spindle.js:425: one 4% roll per spin (Max Luck deliberately left out).
    if (SPINDLE_TOOLS.includes(recipe.tool) && spellboundSpindle(upgrades, rng)) {
      batchExtras.swap = { from: 'thread', to: 'string' };
      batchExtras.lines.push('The Giants have favored you and instead of spinning thread you spun String!');
    }
  }
  batchExtras.xp = (Number(batchExtras.xp) || 0) + recipeXp;
  const swap = batchExtras.swap;
  for (const out of recipe.outputs || []) {
    addItem(inv, swap && out.classTsid === swap.from ? swap.to : out.classTsid, out.qty);
  }
  if (unitIndex === batchQty) {
    // loomer.js:307-312 onMakingComplete: Wondrous Weave, +2 General Fabric.
    if (String(recipe.id) === WONDROUS_WEAVE_RECIPE && wondrousWeave(upgrades, rng, Boolean(opts.maxLuck))) {
      addItem(inv, 'general_fabric', 2);
      batchExtras.items.push({ classTsid: 'general_fabric', qty: 2 });
      batchExtras.lines.push('Hey, look at that. The Giants have favored you with 2 bonus General Fabrics. Lucky you!');
    }
    // inc_making.js:840-928: Bonus Tool From Spare Parts on the Tinkertool.
    if (recipe.tool === 'tinkertool') {
      const firstOut = recipe.outputs?.[0]?.classTsid;
      const gift = rollBonusTool(upgrades, Number(ITEM_CATALOG[firstOut]?.baseCost) || 0, rng, Boolean(opts.maxLuck));
      if (gift) {
        addItem(inv, gift, 1);
        const label = ITEM_CATALOG[gift]?.label || gift;
        batchExtras.items.push({ classTsid: gift, qty: 1 });
        batchExtras.lines.push(`You took the extra parts and made ${/^[aeiou]/i.test(label) ? 'an' : 'a'} ${label}.`);
      }
    }
  }
  // rollCraftingBonusImagination: the tool's *_imagination card can pay a
  // share of the output's base cost as bonus iMG.
  const outputValue = (recipe.outputs || []).reduce(
    (sum, out) => sum + (Number(ITEM_CATALOG[out.classTsid]?.baseCost) || 0) * (Number(out.qty) || 0),
    0
  );
  // tool_base rollCraftingBonusImagination: stats_add_xp(change, false), and
  // "Hey, you got N bonus imagination" names what landed.
  const bonusImagination = grantMoodXp(pc, rollMakingBonusImagination(recipe.tool, upgrades, outputValue, opts.rng || Math.random, Boolean(opts.maxLuck)));

  const unitWear = batchWearUnits(recipe, unitIndex) - batchWearUnits(recipe, unitIndex - 1);
  const wearPoints = recipe.tool && opts.toolState && unitWear > 0 ? wearFor(baseWear * unitWear) : 0;
  const toolUse = wearPoints > 0 ? useToolCondition(opts.toolState, wornTool, wearPoints) : null;

  const toolLabel = TOOL_CATALOG[wornTool]?.label || wornTool || 'hands';
  const outLabels = (recipe.outputs || [])
    .map((o) => `${o.qty}× ${ITEM_CATALOG[o.classTsid]?.label || o.classTsid}`)
    .join(', ');
  return {
    ok: true,
    reason: 'crafted',
    recipe,
    recipeKey,
    msgs: [
      `You made ${recipe.name} with ${toolLabel} (${outLabels}). −${energyLost} energy, +${recipeXp} iMG.`,
      ...(bonusImagination ? [`Bonus imagination! +${bonusImagination} iMG.`] : []),
      ...(unitIndex === 1 && swap ? [batchExtras.lines[0]] : []),
      ...(toolUse?.broke ? [toolUse.msg] : []),
    ],
    toolUse,
    xp: recipeXp,
    bonusImagination,
    // for tests / rollback inspection
    _before: { energy: beforeE, imagination: beforeImg, xp: beforeXp },
  };
}

/**
 * Progress line while crafting quantity N (original: “Making i of N”).
 * @param {number} i  1-based index of the unit currently finishing
 * @param {number} of total requested
 * @param {string} [recipeName]
 */
export function formatCraftProgress(i, of, recipeName = '') {
  // MakingToolAnimator.as 115 shows "Making i of N"; the recipe name after a colon is the remake's.
  const name = recipeName ? `: ${recipeName}` : '';
  return `Making ${i} of ${of}${name}`;
}

const TOOL_CRAFT_DURATION_MS = {
  knife_and_board: 1600,
  frying_pan: 1900,
  blender: 1700,
  gassifier: 2100,
  bubble_tuner: 1800,
  fruit_changing_machine: 2000,
  spice_mill: 1600,
  smelter: 2600,
  ore_grinder: 2200,
  alchemical_tongs: 2400,
  metalmaker: 2600,
  saucepan: 1900,
  mike_tyson_grill: 2000,
  cocktail_shaker: 1700,
  awesome_pot: 2200,
  egg_seasoner: 2000,
  bean_seasoner: 2000,
  cauldron: 2600,
  tincturing_kit: 2400,
  test_tube: 900,
  beaker: 1800,
  crystallizer: 2600,
  woodworker: 2400,
  fuelmaker: 2600,
  loomer: 2000,
  blockmaker: 2600,
  spindle: 2000,
  splendid_spindle: 2000,
  tinkertool: 3000,
};

/**
 * Duration for one visible making cycle. Prefer the GSJS-derived recipe wait,
 * with a tool-specific fallback for embedded and future recipes.
 * @param {Recipe|string|null} recipeOrTool
 */
export function craftDurationFor(recipeOrTool, learned, upgrades = []) {
  const recipe = typeof recipeOrTool === 'object' ? recipeOrTool : null;
  const tool = typeof recipeOrTool === 'string' ? recipeOrTool : recipe?.tool;
  // Cooking level 2+, unskilled transmogrification, and Refining II scale
  // the visible cycle the same way the source scales wait_ms.
  const multiplier = recipe ? makingSkillAdjustments(recipe, learned, upgrades).waitMultiplier : 1;
  const sourceWait = Number(recipe?.waitMs);
  if (Number.isFinite(sourceWait) && sourceWait > 0) {
    return Math.max(350, Math.min(12000, Math.round(Math.max(700, Math.min(6000, sourceWait)) * multiplier)));
  }
  return Math.round((TOOL_CRAFT_DURATION_MS[tool] || 1800) * multiplier);
}

/**
 * Pure timer state for an animated, per-unit making session.
 * Inventory mutation deliberately happens outside this helper when unitsReady > 0.
 */
export function createCraftSession({ recipeKey, recipeName = '', tool = '', qty = 1, durationMs, durations } = {}) {
  const total = Math.max(1, Math.floor(Number(qty) || 1));
  const duration = Math.max(1, Number(durationMs) || craftDurationFor(tool));
  return {
    recipeKey: recipeKey || '',
    recipeName,
    tool,
    qty: total,
    durationMs: duration,
    // Optional per-unit durations (transmogrification's sliding scale).
    durations: Array.isArray(durations) ? durations.map((d) => Math.max(1, Number(d) || duration)) : null,
    completed: 0,
    unitElapsedMs: 0,
    unitProgress: 0,
    totalProgress: 0,
    status: 'running',
  };
}

function unitDuration(session) {
  return session.durations?.[session.completed] ?? session.durationMs;
}

/**
 * Per-unit visible durations for a batch, or null when every unit takes
 * craftDurationFor: transmogrifiers follow making_get_transmogrification_time
 * (doubled unskilled) and machines add MACHINE_EXTRA_WAIT_MS to the first unit.
 */
export function craftUnitDurations(recipe, qty, learned, upgrades = []) {
  const n = Math.max(1, Math.floor(Number(qty) || 1));
  const adjust = makingSkillAdjustments(recipe, learned, upgrades);
  if (adjust.makingType === 'transmogrification') {
    return Array.from({ length: n }, (_, i) => Math.round(transmogUnitSeconds(i + 1) * 1000 * adjust.waitMultiplier));
  }
  if (adjust.makingType === 'machine') {
    const each = craftDurationFor(recipe, learned, upgrades);
    return Array.from({ length: n }, (_, i) => each + (i === 0 ? MACHINE_EXTRA_WAIT_MS : 0));
  }
  return null;
}

/** Advance a making timer without touching inventory or player stats. */
export function advanceCraftSession(session, deltaMs) {
  const next = { ...session };
  let unitsReady = 0;
  if (next.status !== 'running') return { session: next, unitsReady };

  let remaining = Math.max(0, Number(deltaMs) || 0);
  while (remaining > 0 && next.status === 'running') {
    const needed = Math.max(0, unitDuration(next) - next.unitElapsedMs);
    if (remaining < needed) {
      next.unitElapsedMs += remaining;
      remaining = 0;
    } else {
      remaining -= needed;
      next.completed += 1;
      unitsReady += 1;
      next.unitElapsedMs = 0;
      if (next.completed >= next.qty) next.status = 'complete';
    }
  }

  next.unitProgress = next.status === 'complete'
    ? 1
    : Math.max(0, Math.min(1, next.unitElapsedMs / unitDuration(next)));
  next.totalProgress = Math.max(
    0,
    Math.min(1, (next.completed + (next.status === 'running' ? next.unitProgress : 0)) / next.qty)
  );
  return { session: next, unitsReady };
}

/** Cancel only the unfinished portion; completed units remain completed. */
export function cancelCraftSession(session) {
  if (!session || session.status !== 'running') return session ? { ...session } : null;
  return { ...session, status: 'cancelled' };
}

/**
 * @param {{
 *   made: number,
 *   recipeName: string,
 *   energy: number,
 *   xp: number,
 * }} result
 */
export function formatCraftResultLine(result) {
  if (!result || !result.made) return '';
  const n = result.made;
  const name = result.recipeName || 'item';
  const e = result.energy || 0;
  const xp = result.xp || 0;
  // players/inc_making.js 896-909: "You made <name> (x<count>) -3 energy, +2 iMG."
  const meta = [];
  if (e) meta.push(`${e < 0 ? e : `+${e}`} energy`);
  if (xp) meta.push(`${xp > 0 ? `+${xp}` : xp} iMG`);
  return `You made ${name} (x${n})${meta.length ? ` ${meta.join(', ')}` : ''}.`;
}

/** Build the shared result payload after one or more units have been crafted. */
export function buildCraftBatchResult(inv, pc, recipeKey, made, qtyRequested = made, opts = {}) {
  ensureMakingItems();
  const recipe = RECIPE_CATALOG[recipeKey];
  const count = Math.max(0, Math.floor(Number(made) || 0));
  if (!recipe || count < 1) return null;

  const energy = -recipeEnergyCost(recipe, opts.learned) * count;
  const extras = batchExtras?.recipeKey === recipeKey ? batchExtras : null;
  // What landed after the mood bonus (craftRecipe sums it per unit).
  const xp = Number.isFinite(extras?.xp) ? extras.xp : (recipe.xpReward || 0) * count;
  const used = (recipe.inputs || []).map((input) => ({
    classTsid: input.classTsid,
    qty: input.qty * count,
    remain: countItem(inv, input.classTsid),
    label: ITEM_CATALOG[input.classTsid]?.label || input.classTsid,
  }));
  const swapped = (id) => (extras?.swap && id === extras.swap.from ? extras.swap.to : id);
  const outputs = (recipe.outputs || []).map((output) => ({
    classTsid: swapped(output.classTsid),
    qty: output.qty * count,
    label: ITEM_CATALOG[swapped(output.classTsid)]?.label || swapped(output.classTsid),
  }));
  for (const item of extras?.items || []) {
    outputs.push({ classTsid: item.classTsid, qty: item.qty, label: ITEM_CATALOG[item.classTsid]?.label || item.classTsid, bonus: true });
  }
  const canMakeMore = canCraft(inv, recipe, opts).ok
    && (pc.energy || 0) >= recipeEnergyCost(recipe, opts.learned);
  const activityLine = [
    formatCraftResultLine({
      made: count,
      recipeName: recipe.name,
      energy,
      xp,
    }),
    ...(extras?.lines || []),
  ].join(' ');

  return {
    made: count,
    qtyRequested: Math.max(count, Math.floor(Number(qtyRequested) || count)),
    recipeKey,
    recipeName: recipe.name,
    energy,
    xp,
    outputs,
    used,
    canMakeMore,
    activityLine,
    headline: count === 1
      ? `You made ${recipe.name}!`
      : `You made ${count} ${recipe.name}${recipe.name.endsWith('s') ? '' : 's'}!`,
  };
}

/**
 * Craft up to `qty` units of a recipe, recording per-unit progress and a final result
 * payload the Make UI can show (progress “i of N” → result with energy/xp + make-more).
 *
 * Mutates inv/pc only for successful units (same as repeated craftRecipe).
 *
 * @param {import('./inventory.js').Inventory} inv
 * @param {object} pc
 * @param {string} recipeKey
 * @param {number} qty
 * @param {{ learned?: string[], requireSkill?: boolean, requireTool?: boolean }} [opts]
 * @returns {{
 *   ok: boolean,
 *   made: number,
 *   qtyRequested: number,
 *   recipeKey: string,
 *   recipe: Recipe|null,
 *   progress: { i: number, of: number, label: string, energy: number, xp: number }[],
 *   result: null | {
 *     made: number,
 *     recipeKey: string,
 *     recipeName: string,
 *     energy: number,
 *     xp: number,
 *     outputs: { classTsid: string, qty: number, label: string }[],
 *     used: { classTsid: string, qty: number, remain: number, label: string }[],
 *     canMakeMore: boolean,
 *     activityLine: string,
 *     headline: string,
 *   },
 *   msgs: string[],
 *   reason?: string,
 * }}
 */
export function craftRecipeBatch(inv, pc, recipeKey, qty = 1, opts = {}) {
  ensureMakingItems();
  const recipe = RECIPE_CATALOG[recipeKey];
  const n = Math.max(1, Math.floor(Number(qty) || 1));
  if (!recipe) {
    return {
      ok: false,
      made: 0,
      qtyRequested: n,
      recipeKey,
      recipe: null,
      progress: [],
      result: null,
      msgs: ['Unknown recipe.'],
      reason: 'unknown',
    };
  }

  const progress = [];
  let made = 0;
  let lastFail = null;

  for (let i = 1; i <= n; i++) {
    const r = craftRecipe(inv, pc, recipeKey, { ...opts, unitIndex: i, batchQty: n });
    if (!r.ok) {
      lastFail = r;
      break;
    }
    made += 1;
    const eCost = recipeEnergyCost(recipe, opts.learned, opts.upgrades || pc?.imaginationUpgrades || []);
    const xpGain = Number.isFinite(r.xp) ? r.xp : recipe.xpReward || 0;
    progress.push({
      i,
      of: n,
      label: formatCraftProgress(i, n, recipe.name),
      energy: -eCost,
      xp: xpGain,
    });
  }

  if (made === 0) {
    return {
      ok: false,
      made: 0,
      qtyRequested: n,
      recipeKey,
      recipe,
      progress: [],
      result: null,
      msgs: lastFail?.msgs || ['Cannot craft.'],
      reason: lastFail?.reason || 'fail',
    };
  }

  const result = buildCraftBatchResult(inv, pc, recipeKey, made, n, opts);

  return {
    ok: true,
    made,
    qtyRequested: n,
    recipeKey,
    recipe,
    progress,
    result,
    msgs: [result.activityLine],
  };
}

/**
 * Whether another unit of this recipe can be made now (make-more button).
 * @param {import('./inventory.js').Inventory} inv
 * @param {object} pc
 * @param {string} recipeKey
 * @param {{ learned?: string[], requireSkill?: boolean, requireTool?: boolean }} [opts]
 */
export function canCraftAgain(inv, pc, recipeKey, opts = {}) {
  const recipe = RECIPE_CATALOG[recipeKey];
  if (!recipe) return false;
  const check = canCraft(inv, recipe, opts);
  if (!check.ok) return false;
  return (pc.energy || 0) >= recipeEnergyCost(recipe, opts.learned);
}

/**
 * The demo starter kit: the original remake making tools. Tools added by the
 * full recipe import (saucepan, grill, shaker, pot, seasoners, alchemy kit,
 * machines, loomer) are earned through vendors or Tinkering instead, so the
 * starting pack does not balloon.
 */
export const STARTER_TOOL_IDS = Object.freeze([
  'knife_and_board',
  'frying_pan',
  'blender',
  'gassifier',
  'bubble_tuner',
  'fruit_changing_machine',
  'spice_mill',
  'smelter',
  'ore_grinder',
  'alchemical_tongs',
  'metalmaker',
  'pick',
  'fancy_pick',
  'tinkertool',
]);

/**
 * Starter tools for demo.
 * @param {{ all?: boolean }} [opts]  all: every TOOL_CATALOG tool (QA)
 * @returns {Record<string, number>}
 */
export function starterToolsInventory(opts = {}) {
  const out = {};
  const ids = opts.all ? Object.keys(TOOL_CATALOG) : STARTER_TOOL_IDS;
  for (const id of ids) out[id] = 1;
  return out;
}

/**
 * Demo ingredients so blender/gas/bubble chains are tryable at start.
 * @returns {Record<string, number>}
 */
export function starterCraftIngredients() {
  return {
    grain: 15,
    pinch_of_salt: 5,
    meat: 2,
    orange: 8,
    lemon: 6,
    plum: 4,
    spinach: 3,
    // harvestables also granted lightly so gassifier/bubble paths work offline
    plain_bubble: 20,
    general_vapour: 20,
    all_spice: 8,
    cherry: 20,
  };
}
